#include <DHT.h>

// -------------------------------
// KONFIGURACJA CZUJNIKA DHT
// -------------------------------

#define DHTPIN 12
#define DHTTYPE DHT11
// Dla DHT22 zmien na DHT22

DHT dht(DHTPIN, DHTTYPE);

// -------------------------------
// ZMIENNE
// -------------------------------

int liczba = 0;

int minimum, maksimum;
int jasnosc = 0;
int wilgotnosc = 0;
int temperatura = 0;

char tryb = 'L';

unsigned long czasPomiaru = 0;
unsigned long czasPrzycisku = 0;

bool poprzedniStanPrzycisku = HIGH;
bool stanPrzycisku = HIGH;

// -------------------------------
// CYFRY WYSWIETLACZA
// Wspolna anoda
// -------------------------------

const byte cyfry[10] = {
  0b0000001, // 0
  0b1001111, // 1
  0b0010010, // 2
  0b0000110, // 3
  0b1001100, // 4
  0b0100100, // 5
  0b0100000, // 6
  0b0001111, // 7
  0b0000000, // 8
  0b0000100  // 9
};

// -------------------------------
// FUNKCJA WYSWIETLANIA CYFRY
// -------------------------------

void Znak(int numer) {

  numer = constrain(numer, 0, 9);

  byte wzor = cyfry[numer];

  // Segmenty A-F: D2-D7
  byte portD = ((wzor >> 1) & 0b00111111) << 2;

  // Segment G: D8
  byte portB = wzor & 1;

  PORTD = (PORTD & 0b00000011) | portD;

  if (portB) {
    PORTB |= 0b00000001;
  } else {
    PORTB &= 0b11111110;
  }
}

// -------------------------------
// MULTIPLEKSOWANIE
// -------------------------------

void Wyswietl() {

  // Wylacz obie cyfry
  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  // Dziesiatki
  Znak(liczba / 10);

  digitalWrite(10, HIGH);
  delay(2);
  digitalWrite(10, LOW);

  // Jednosci
  Znak(liczba % 10);

  digitalWrite(11, HIGH);
  delay(2);
  digitalWrite(11, LOW);
}

// -------------------------------
// POMIAR CZUJNIKOW
// -------------------------------

void Pomiar() {

  // Pomiar jasnosci
  int odczyt = analogRead(A0);

  if (odczyt < minimum) minimum = odczyt;
  if (odczyt > maksimum) maksimum = odczyt;

  if (maksimum > minimum) {
    jasnosc = map(odczyt, minimum, maksimum, 0, 99);
  } else {
    jasnosc = 0;
  }

  jasnosc = constrain(jasnosc, 0, 99);

  // Pomiar wilgotnosci
  float h = dht.readHumidity();

  // Pomiar temperatury
  float t = dht.readTemperature();

  // Sprawdzenie poprawnosci odczytu
  if (!isnan(h)) {
    wilgotnosc = constrain((int)h, 0, 99);
  }

  if (!isnan(t)) {
    temperatura = constrain((int)t, 0, 99);
  }

  // Wybor wartosci do wyswietlenia
  switch (tryb) {

    case 'L':
      liczba = jasnosc;
      break;

    case 'H':
      liczba = wilgotnosc;
      break;

    case 'T':
      liczba = temperatura;
      break;
  }
}

// -------------------------------
// OBSLUGA PRZYCISKU
// -------------------------------

void Przycisk() {

  bool odczyt = digitalRead(9);

  if (odczyt != poprzedniStanPrzycisku) {
    czasPrzycisku = millis();
  }

  if (millis() - czasPrzycisku > 40) {

    if (odczyt != stanPrzycisku) {

      stanPrzycisku = odczyt;

      // Reakcja na nacisniecie
      if (stanPrzycisku == LOW) {

        switch (tryb) {

          case 'L':
            tryb = 'H';
            break;

          case 'H':
            tryb = 'T';
            break;

          case 'T':
            tryb = 'L';
            break;
        }

        switch (tryb) {

          case 'L':
            liczba = jasnosc;
            break;

          case 'H':
            liczba = wilgotnosc;
            break;

          case 'T':
            liczba = temperatura;
            break;
        }
      }
    }
  }

  poprzedniStanPrzycisku = odczyt;
}

// -------------------------------
// SETUP
// -------------------------------

void setup() {

  // Segmenty D2-D7
  DDRD |= 0b11111100;

  // D8, D10, D11 jako wyjscia
  DDRB |= 0b00001101;

  // Przycisk D9
  pinMode(9, INPUT_PULLUP);

  // Czujnik DHT
  dht.begin();

  // Wylaczenie cyfr
  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  // Kalibracja poczatkowa jasnosci
  minimum = analogRead(A0);
  maksimum = minimum;

  delay(2000);

  Pomiar();
}

// -------------------------------
// LOOP
// -------------------------------

void loop() {

  // Ciagle odswiezanie wyswietlacza
  Wyswietl();

  // Obsluga przycisku
  Przycisk();

  // Pomiar co 2 sekundy
  if (millis() - czasPomiaru >= 2000) {

    czasPomiaru = millis();

    Pomiar();
  }
}
